(async () => {
  const { readFileSync, existsSync } = await import('node:fs');
  const pngPath = process.env.PNG_PATH;
  const outPath = process.env.OUTPUT_PATH;
  if (!pngPath) throw new Error('Missing PNG_PATH');
  if (!outPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(pngPath)) throw new Error('PNG file not found');
  const raw = readFileSync(pngPath, 'utf8').trim();
  const pngBytes = Buffer.from(raw, 'base64');
  globalThis.pngBytes = pngBytes;
  globalThis.outputPath = outPath;
})();

(async () => {
  const { PDFDocument } = await import('pdf-lib');
  const { writeFileSync } = await import('node:fs');
  const pngBytes = globalThis.pngBytes;
  const outputPath = globalThis.outputPath;
  if (!pngBytes) throw new Error('pngBytes not prepared');
  const pdfDoc = await PDFDocument.create();
  const pngImage = await pdfDoc.embedPng(pngBytes);
  const { width, height } = pngImage.scale(1);
  const page = pdfDoc.addPage([width, height]);
  page.drawImage(pngImage, { x: 0, y: 0, width, height });
  const pdfBytes = await pdfDoc.save();
  writeFileSync(outputPath, pdfBytes);
  globalThis.resultPath = outputPath;
})();

(async () => {
  const resultPath = globalThis.resultPath;
  if (!resultPath) throw new Error('resultPath missing');
  console.log(JSON.stringify({ output_path: resultPath }));
})();
